package com.spms.service;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import com.spms.dto.Dtos;import com.spms.entity.*;import com.spms.repository.*;import java.util.*;@Service @RequiredArgsConstructor public class AttendanceService{private final AttendanceRepository repo;private final EmployeeRepository employees;private final UserAccountRepository users;public List<AttendanceRecord> forEmployee(UUID id){return repo.findByEmployeeIdOrderByWorkDateDesc(id);}public AttendanceRecord put(UUID id,Dtos.AttendanceRequest r,String actor){if(r.workDate().isAfter(java.time.LocalDate.now())&& !r.status().equals("HOLIDAY"))throw new IllegalArgumentException("Future attendance is not allowed");var a=repo.findByEmployeeIdAndWorkDate(id,r.workDate()).orElseGet(AttendanceRecord::new);a.setEmployee(employees.findById(id).orElseThrow());a.setWorkDate(r.workDate());a.setStatus(AttendanceRecord.Status.valueOf(r.status()));a.setRemarks(r.remarks());a.setUpdatedBy(users.findByUsername(actor).orElseThrow());return repo.save(a);}}
